<template>
  <div id="app">
    <router-view v-if="1 == 1"></router-view>
    <b-row v-else class="mt-4">
      <b-col></b-col>
      <b-col lg="6" md="8" sm="12"
        ><b-alert class="text-center" variant="danger" show dismissible>
          <h4>
            <b-icon icon="wifi-off" variant="danger"></b-icon> Sem conexão à
            internet
          </h4>
          <!-- <b>&rArr;</b> -->
        </b-alert></b-col
      >
      <b-col></b-col>
    </b-row>

    <b-button
      class="theme-toggle-btn shadow-sm"
      size="sm"
      :variant="isDarkTheme ? 'light' : 'dark'"
      @click="toggleTheme"
      v-b-tooltip.hover
      :title="isDarkTheme ? 'Mudar para modo claro' : 'Mudar para modo escuro'"
    >
      <b-icon :icon="isDarkTheme ? 'sun-fill' : 'moon-stars-fill'" class="mr-1"></b-icon>
      {{ isDarkTheme ? "Claro" : "Escuro" }}
    </b-button>
  </div>
</template>

<script>
import isOnline from "is-online";
import { mapGetters } from "vuex";

export default {
  data: () => ({
    connected: null,
  }),

  computed: {
    ...mapGetters(["uiTheme", "isDarkTheme"]),
  },

  watch: {
    connected: function () {
      console.log(this.connected);
    },
    uiTheme: {
      handler(value) {
        this.applyTheme(value);
      },
      immediate: true,
    },
  },

  async created() {
    this.connected = await isOnline();
  },

  methods: {
    toggleTheme() {
      this.$store.dispatch("toggleUiTheme");
    },
    applyTheme(theme) {
      const activeTheme = theme === "dark" ? "dark" : "light";
      document.body.classList.remove("theme-light", "theme-dark");
      document.body.classList.add(`theme-${activeTheme}`);
    },
  },
};
</script>

