import Vue from "vue";
import VueRouter from "vue-router";
import store from "@/store";

Vue.use(VueRouter);

const normalizeRole = (role) => {
  if (role === null || role === undefined || role === "") return null;
  const parsedRole = Number(role);
  return Number.isNaN(parsedRole) ? null : parsedRole;
};

const getStaffFallbackRoute = (userRole) => {
  if (userRole === 3) return "/gestor";
  if (userRole === 0) return "/company";
  if (userRole >= 1) return "/dashboard";
  return "/";
};

const routes = [
  {
    path: "/",
    name: "Login",
    component: () => import(/* webpackChunkName "login"*/ "../pages/LoginView"),
  },
  {
    path: "/reports",
    name: "Reports",
    component: () =>
      import(/* webpackChunkName "reports"*/ "../pages/ReportsView"),
    meta: {
      requiresAuth: true,
    },
  },
  {
    path: "/dashboard",
    name: "Home",
    component: () =>
      import(/* webpackChunkName "dashboard"*/ "../pages/HomeView"),
    meta: {
      requiresAuth: true,
    },
  },
  {
    path: "/settings",
    name: "Settings",
    component: () =>
      import(/* webpackChunkName "settings"*/ "../pages/SettingsView"),
    meta: {
      requiresAuth: true,
    },
  },
  {
    path: "/customers",
    name: "CustomerView",
    component: () =>
      import(/* webpackChunkName "customer"*/ "../pages/CustomerView"),
    meta: {
      requiresAuth: true,
    },
  },
  {
    path: "/customer",
    name: "BorrowerView",
    component: () =>
      import(/* webpackChunkName "borrower"*/ "../pages/BorrowerView"),
    meta: {
      requiresAuth: true,
    },
  },
  {
    path: "/company",
    name: "CompanyView",
    component: () =>
      import(/* webpackChunkName "Company"*/ "../pages/CompanyView"),
    meta: {
      requiresAuth: true,
      allowedRoles: [0],
    },
  },
  {
    path: "/profile",
    name: "Profile",
    component: () =>
      import(/* webpackChunkName "profile"*/ "../pages/ProfileView"),
    meta: {
      requiresAuth: true,
    },
  },
  {
    path: "/logs",
    name: "SystemLogs",
    component: () =>
      import(/* webpackChunkName "systemLogs"*/ "../pages/SystemLogsView"),
    meta: {
      requiresAuth: true,
    },
  },
  {
    path: "/system_logs",
    name: "LogsView",
    component: () =>
      import(/* webpackChunkName "LogsView"*/ "../pages/LogsView"),
    meta: {
      requiresAuth: true,
    },
  },
  {
    path: "/payments",
    name: "PaymentsView",
    component: () =>
      import(/* webpackChunkName "payments"*/ "../pages/PaymentsView"),
    meta: {
      requiresAuth: true,
    },
  },
  {
    path: "/notificacoes",
    name: "NotificationsView",
    component: () =>
      import(/* webpackChunkName "notificacoes"*/ "../pages/NotificationsView"),
    meta: {
      requiresAuth: true,
    },
  },
  {
    path: "/prestacoes",
    name: "UpcomingInstallments",
    component: () =>
      import(/* webpackChunkName "prestacoes"*/ "../pages/UpcomingInstallmentsView"),
    meta: {
      requiresAuth: true,
    },
  },
  {
    path: "/gestor",
    name: "GestorDashboardView",
    component: () =>
      import(/* webpackChunkName "GestorDashboard"*/ "../pages/GestorDashboardView"),
    meta: {
      requiresAuth: true,
      allowedRoles: [3],
    },
  },
  {
    path: "/customer-dashboard",
    name: "CustomerDashboardView",
    component: () =>
      import(/* webpackChunkName "CustomerDashboardView"*/ "../pages/CustomerDashboardView"),
    meta: {
      requiresCustomerAuth: true,
    },
  },
];

const router = new VueRouter({
  mode: "history",
  routes,
});

router.beforeEach((to, from, next) => {
  const userRole = normalizeRole(store.getters.user?.userRole);

  // Rotas do portal do cliente
  if (to.matched.some((record) => record.meta.requiresCustomerAuth)) {
    const customer = store.getters.customerPanelData;
    if (store.getters.isLoggedIn && customer && customer.accountNumber) {
      next();
      return;
    }
    next("/");
  }
  // Rotas do backoffice (staff)
  else if (to.matched.some((record) => record.meta.requiresAuth)) {
    if (store.getters.isLoggedIn) {
      // Impedir que sessões de cliente acedam ao backoffice
      if (store.getters.isCustomerSession) {
        next("/customer-dashboard");
        return;
      }

      // Impedir acesso por URL a rotas sem permissão de perfil
      const protectedRecord = to.matched.find(
        (record) =>
          Array.isArray(record.meta.allowedRoles) &&
          record.meta.allowedRoles.length > 0
      );
      if (protectedRecord) {
        const allowedRoles = protectedRecord.meta.allowedRoles.map((role) =>
          Number(role)
        );
        if (userRole === null || !allowedRoles.includes(userRole)) {
          next(getStaffFallbackRoute(userRole));
          return;
        }
      }

      next();
      return;
    }
    next("/");
  } else {
    next();
  }
});

export default router;
