import Vue from 'vue'
import moment from 'moment'

const getValidMoment = (value) => {
    if (value === null || value === undefined || value === '') return null
    const parsed = moment(value)
    return parsed.isValid() ? parsed : null
}

Vue.directive('money-format', (el, { value }) => {
    el.innerHTML = new Intl.NumberFormat('pt-PT', {
        currency: 'MZN',
        style: 'currency',
        minimumFractionDigits: 2
    }).format(value || 0)
})

Vue.directive('date-format', (el, { value }) => {
    const parsed = getValidMoment(value)
    el.innerHTML = parsed ? parsed.format('DD/MM/YYYY') : '--'
})
